#include "team04_race/lidar_planner.hpp"
#include <fstream>
#include <iostream>
#include <chrono>
int main(int argc,char**argv){if(argc<2)return 2;std::ifstream in(argv[1]);std::vector<team04::Point>p;team04::Point q;while(in>>q.x>>q.y>>q.z)p.push_back(q);for(double horizon:{6.,8.,10.,12.})for(auto mode:{"centerline","racing_line"}){team04::PlannerConfig c;c.path_mode=mode;c.max_speed=argc>2?std::stod(argv[2]):3;c.lateral_acceleration=argc>4?std::stod(argv[4]):.35;c.braking=argc>5?std::stod(argv[5]):.7;c.acceleration=argc>6?std::stod(argv[6]):.3;c.min_obstacle_height=argc>7?std::stod(argv[7]):.035;c.visibility_buffer=argc>8?std::stod(argv[8]):.8;c.planning_horizon=horizon;auto start=std::chrono::steady_clock::now();auto r=team04::planLidar(p,c,argc>3?std::stod(argv[3]):2.7);double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::cout<<"{\"mode\":\""<<mode<<"\",\"horizon\":"<<horizon<<",\"valid\":"<<(r.valid?"true":"false")<<",\"reason\":\""<<r.reason<<"\",\"speed\":"<<r.speed<<",\"free_distance\":"<<r.free_distance<<",\"ms\":"<<ms<<",\"candidates\":"<<r.candidate_count<<",\"sparse_links\":"<<r.observed_sparse_links<<",\"obstacles\":"<<r.obstacles.size()<<",\"ground_a\":"<<r.ground_a<<",\"ground_b\":"<<r.ground_b<<",\"ground_c\":"<<r.ground_c<<",\"lookahead\":"<<r.effective_lookahead<<",\"racing_selected\":"<<(r.racing_selected?"true":"false")<<",\"offset\":"<<r.max_offset<<",\"center_time\":"<<r.center_time<<",\"racing_time\":"<<r.predicted_time<<"}"<<std::endl;}}
